#!/usr/bin/env python3
"""Record an explicitly requested early delivery without claiming an unfinished hour passed."""
from pathlib import Path
import datetime,hashlib,json,sys
repo=Path(__file__).resolve().parents[1];root=Path(sys.argv[1]);historical=Path(sys.argv[2]);validation=Path(sys.argv[3])
sources={str(p.relative_to(repo)):hashlib.sha256(p.read_bytes()).hexdigest()for p in sorted((repo/'src').rglob('*'))if p.suffix in ['.js','.cjs']}
started=json.loads((root/'started.json').read_text());assert sources==started['sourceHashes']
progress=next(json.loads(line)for line in reversed((root/'harness.log').read_text().splitlines())if line.startswith('{'))
old=json.loads((historical/'soak-result.json').read_text());assert old['passed']and old['seconds']>=3600
recovery=json.loads((validation/'recovery-mcp-final/recovery-results.json').read_text());mcp=json.loads((validation/'packaged-integration/integration-results.json').read_text());native=json.loads((validation/'windows-native-results.json').read_text());ui=json.loads((validation/'packaged-ui/ui-smoke.json').read_text());clients=json.loads((root/'clients-results.json').read_text())
assert len(recovery)==11 and all(x['passed']for x in recovery)
assert len(mcp)==54 and all(x['passed']for x in mcp)and len({x['name']for x in mcp})==37
assert len(clients)==32 and all(x['passed']for x in clients)and native['passed']
data={'applicationVersion':'2.0.0','branch':'recovery/current-public-relay-pro','passed':False,'deliveryRequestedBeforeFinalHour':True,'status':'User explicitly requested immediate complete source/runtime upload and local project-manager registration; final-source hour is incomplete at this snapshot.','recordedAtUtc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'runtime':{'electron':'44.8.0','builtInNode':'24.22.0','requiresSystemNode':False},'oneHour':{'passed':False,'completed':False,'seconds':progress['seconds'],'startedAtUtc':started['startedAtUtc'],'progress':progress},'historicalBaselineHour':{'passed':True,'seconds':old['seconds'],'sameAsFinalSources':old['sourceHashes']==sources,'note':'Earlier source version; this is not acceptance of the final source version.'},'publicChecks':{'rawSdkConnections':32,'allRawSdkPassed':True,'mcpIntegrationCalls':54,'mcpToolNames':37,'mcpPrompts':5},'automaticRecovery':[{k:x[k]for k in ['name','passed','seconds','mcpAutomaticallyRecovered']if k in x}for x in recovery],'desktop':ui,'nativeWindows':native,'sourceHashes':sources,'limitations':['Final-source continuous one-hour acceptance is incomplete at the user-requested delivery snapshot.','Windows ZIP Setup double-click, physical tray interaction and actual OS boot/restart were not tested.','Linux GUI used Xvfb; physical Linux tray and OS boot/restart were not tested.','Database business workloads and scheduler registration were not accepted against actual services.','Automatic recovery creates new verified connections and never blindly replays interrupted operations.'],'privacy':'No credentials, connection blocks or raw runtime logs included.'}
for p in [repo/'docs/PRO-VALIDATION.json',repo/'deliverables/pro/VALIDATION.json']:p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'snapshotCreated':True,'finalHourCompleted':False,'seconds':progress['seconds'],'sourceFiles':len(sources)}))
